{"path": "tax.py", "content": "from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")


def line_tax(price, rate):
    """Tax for one line, rounded half-up to whole cents (0.125 -> 0.13)."""
    tax = Decimal(str(price)) * Decimal(str(rate))
    return tax.quantize(CENT, rounding=ROUND_HALF_UP)
"}

